def test_computed_write_invalidates_prior_object_fields(tmp_path):
    f, db, _ = frontend(tmp_path, '''function add() {
      var body={key:"old"}; body[unknown()]="new";
      $.ajax({url:"/books",type:"POST",data:JSON.stringify(body)});
    }''')
