def test_reassigned_payload_does_not_keep_old_literal(tmp_path):
    f, _, _ = frontend(tmp_path, '''function add() {
      var body={key:"old"}; body=unknown();
      $.ajax({url:"/books",type:"POST",data:JSON.stringify(body)});
    }''')
